function toPlain(value, seen = new WeakSet()) {
  if (typeof value !== "object" || value === null) return value;
  if (seen.has(value)) return "[circular]";
  seen.add(value);
  const out = {};
  for (const [key, child] of Object.entries(value)) out[key] = toPlain(child, seen);
  seen.delete(value);
  return out;
}
const address = { city: "Lagos" };
console.log(JSON.stringify(toPlain({ billing: address, shipping: address })));

