function memoizeByObject(fn) {
  const cache = new WeakMap();
  return (obj) => {
    if (cache.has(obj)) return cache.get(obj);
    const result = fn(obj);
    cache.set(obj, result);
    return result;
  };
}

let calls = 0;
const discount = memoizeByObject((customer) => {
  calls += 1;
  return customer.vip ? 1000 : undefined;
});

